package vn.codex.garenapopup;
import android.app.Service;import android.content.*;import android.graphics.Color;import android.graphics.PixelFormat;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class FloatingService extends Service {
 private WindowManager wm;private FrameLayout root,menu;private Spinner accountSpinner;private ImageView collapsedIcon;private TextView accountInfo,status,title;private int index,menuWidth,menuHeight;private boolean spinnerReady;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable refresh=new Runnable(){public void run(){if(status!=null){status.setText(statusText());updateAccountInfo();handler.postDelayed(this,700);}}};
 @Override public IBinder onBind(Intent i){return null;}@Override public void onCreate(){super.onCreate();index=prefs().getInt("selectedIndex",0);showPanel();}
 private android.content.SharedPreferences prefs(){return getSharedPreferences("login",MODE_PRIVATE);}private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);}private GradientDrawable bg(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}private GradientDrawable outline(int fill,int stroke,int radius,float width){GradientDrawable d=bg(fill,radius);d.setStroke(dp(width),stroke);return d;}private String statusText(){String value=prefs().getString("state","Sẵn sàng");return value.toLowerCase(java.util.Locale.ROOT).startsWith("đã chọn")?"Sẵn sàng":value;}
 private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setIncludeFontPadding(false);t.setSingleLine(true);t.setEllipsize(android.text.TextUtils.TruncateAt.END);return t;}
 private void place(View view,float x,float y,float w,float h){int width=Math.max(1,Math.round(menuWidth*w/100f)),height=Math.max(1,Math.round(menuHeight*h/100f));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(width,height);p.leftMargin=Math.round(menuWidth*x/100f-width/2f);p.topMargin=Math.round(menuHeight*y/100f-height/2f);menu.addView(view,p);}
 private TextView actionButton(String text,float x,float y,float w,float h,View.OnClickListener listener){TextView b=label(text,18,Color.parseColor("#00e5ff"));b.setTypeface(null,Typeface.BOLD);b.setBackground(outline(Color.parseColor("#081a17"),Color.parseColor("#00e5ff"),9,1.5f));place(b,x,y,w,h);b.setOnClickListener(listener);return b;}
 private void showPanel(){int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;wm=(WindowManager)getSystemService(WINDOW_SERVICE);int sw=getResources().getDisplayMetrics().widthPixels,sh=getResources().getDisplayMetrics().heightPixels;int availableW=Math.max(dp(1),sw-dp(24)),availableH=Math.max(dp(1),sh-dp(48));int designBase=Math.max(dp(1),Math.min(dp(420),Math.min(availableW,availableH)));menuWidth=Math.round(designBase*.88f);menuHeight=Math.round(designBase*.72f);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(menuWidth,menuHeight,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;lp.y=dp(32);
  root=new FrameLayout(this);menu=new FrameLayout(this);GradientDrawable panel=bg(Color.parseColor("#081a17"),17);panel.setStroke(dp(2),Color.parseColor("#00e5ff"));menu.setBackground(panel);try{root.setAlpha(Math.max(.2f,Math.min(1f,Float.parseFloat(prefs().getString("overlayOpacity","85"))/100f)));}catch(Exception ignored){root.setAlpha(.85f);}
  title=label("Auto Login",22,Color.parseColor("#00e5ff"));title.setTypeface(null,Typeface.BOLD);title.setBackground(outline(Color.parseColor("#081a17"),Color.parseColor("#00e5ff"),14,2));place(title,50,10,60,15);title.setOnTouchListener(drag(lp));
  status=label(statusText(),14,Color.parseColor("#35f36e"));place(status,50,91,50,10);
  accountInfo=label("",15,Color.WHITE);accountInfo.setBackground(bg(Color.parseColor("#12161a"),0));place(accountInfo,50,28,96,10);
  TextView prev=label("< TRƯỚC",16,Color.WHITE);prev.setBackground(outline(Color.parseColor("#10202a"),Color.parseColor("#00cfe8"),5,1));place(prev,25,45,44,15);prev.setOnClickListener(v->select(index-1));
  TextView next=label("SAU >",16,Color.WHITE);next.setBackground(outline(Color.parseColor("#10202a"),Color.parseColor("#00cfe8"),5,1));place(next,75,45,44,15);next.setOnClickListener(v->select(index+1));
  accountSpinner=new Spinner(this);accountSpinner.setBackground(outline(Color.parseColor("#0d1117"),Color.parseColor("#00cfe8"),4,1));accountSpinner.setPadding(dp(12),0,dp(12),0);accountSpinner.setPopupBackgroundDrawable(bg(Color.parseColor("#0d1117"),4));place(accountSpinner,50,65,96,15);loadAccountSpinner();
  actionButton("KILL",13,91,20,10,v->android.os.Process.killProcess(android.os.Process.myPid()));actionButton("CLOSE",87,91,20,10,v->collapse(lp));
  int floatingSize=56;try{int level=Integer.parseInt(prefs().getString("overlaySize","2"));floatingSize=level==1?44:level==3?68:56;}catch(Exception ignored){}collapsedIcon=new ImageView(this);collapsedIcon.setImageResource(R.drawable.ic_launcher_art);collapsedIcon.setScaleType(ImageView.ScaleType.CENTER_CROP);collapsedIcon.setBackground(bg(0xff14233d,100));collapsedIcon.setClipToOutline(true);collapsedIcon.setVisibility(View.GONE);root.addView(menu,new FrameLayout.LayoutParams(-1,-1));root.addView(collapsedIcon,new FrameLayout.LayoutParams(dp(floatingSize),dp(floatingSize),Gravity.CENTER));collapsedIcon.setTag(floatingSize);wm.addView(root,lp);handler.postDelayed(refresh,700);collapsedIcon.setContentDescription("Mở menu Auto Login Garena");collapsedIcon.setOnTouchListener(collapsedTouch(lp));updateAccountInfo();
 }
 private void loadAccountSpinner(){JSONArray a=accounts();java.util.ArrayList<String> names=new java.util.ArrayList<>();for(int n=0;n<a.length();n++)try{names.add(String.format(java.util.Locale.ROOT,"%02d. %s",n+1,a.getJSONObject(n).getString("user")));}catch(Exception ignored){}if(names.isEmpty())names.add("Chưa nạp tài khoản");ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,names){@Override public View getView(int position,View convert,android.view.ViewGroup parent){TextView t=(TextView)super.getView(position,convert,parent);t.setText("▾ Danh sách tài khoản ▾");t.setGravity(Gravity.CENTER);t.setTextColor(Color.WHITE);t.setTextSize(16);return t;}@Override public View getDropDownView(int position,View convert,android.view.ViewGroup parent){TextView t=(TextView)super.getDropDownView(position,convert,parent);t.setTextColor(Color.WHITE);t.setBackgroundColor(Color.parseColor("#0d1117"));t.setPadding(dp(12),dp(10),dp(12),dp(10));return t;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);accountSpinner.setAdapter(adapter);spinnerReady=false;if(a.length()>0)accountSpinner.setSelection(Math.min(index,a.length()-1));accountSpinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){if(spinnerReady&&position!=index)select(position);}public void onNothingSelected(android.widget.AdapterView<?> p){}});accountSpinner.post(()->spinnerReady=true);}
 private View.OnTouchListener drag(WindowManager.LayoutParams lp){return new View.OnTouchListener(){float sx,sy;int ox,oy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){sx=e.getRawX();sy=e.getRawY();ox=lp.x;oy=lp.y;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){lp.x=ox+(int)(e.getRawX()-sx);lp.y=oy+(int)(e.getRawY()-sy);wm.updateViewLayout(root,lp);return true;}return true;}};}
 private View.OnTouchListener collapsedTouch(WindowManager.LayoutParams lp){return new View.OnTouchListener(){float sx,sy;int ox,oy;boolean moved;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){sx=e.getRawX();sy=e.getRawY();ox=lp.x;oy=lp.y;moved=false;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.abs(dx)>dp(6)||Math.abs(dy)>dp(6))moved=true;if(moved){lp.x=ox+(int)dx;lp.y=oy+(int)dy;wm.updateViewLayout(root,lp);}return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(!moved)expand(lp);return true;}return true;}};}
 private void collapse(WindowManager.LayoutParams lp){menu.setVisibility(View.GONE);collapsedIcon.setVisibility(View.VISIBLE);int size=collapsedIcon.getTag() instanceof Integer?(Integer)collapsedIcon.getTag():56;lp.width=dp(size);lp.height=dp(size);wm.updateViewLayout(root,lp);}
 private void expand(WindowManager.LayoutParams lp){collapsedIcon.setVisibility(View.GONE);menu.setVisibility(View.VISIBLE);lp.width=menuWidth;lp.height=menuHeight;wm.updateViewLayout(root,lp);}
 private JSONArray accounts(){try{return new JSONArray(prefs().getString("accounts_json","[]"));}catch(Exception e){return new JSONArray();}}
 private void select(int target){JSONArray a=accounts();if(a.length()==0){prefs().edit().putString("state","Chưa có danh sách tài khoản").apply();return;}index=(target%a.length()+a.length())%a.length();try{JSONObject o=a.getJSONObject(index);prefs().edit().putInt("selectedIndex",index).putString("user",o.getString("user")).putString("pass",o.getString("pass")).putBoolean("fillPending",true).putInt("loginStage",0).putString("state","Sẵn sàng").apply();if(accountSpinner!=null&&accountSpinner.getSelectedItemPosition()!=index)accountSpinner.setSelection(index);updateAccountInfo();Intent i=new Intent("vn.codex.garenapopup.COMMAND");i.putExtra("command","FILL_ACCOUNT");sendBroadcast(i);}catch(Exception ignored){}}
 private void updateAccountInfo(){if(accountInfo==null)return;JSONArray a=accounts();String name=prefs().getString("user","Chưa chọn acc");accountInfo.setText("Số lượng: "+(a.length()==0?"0/0":(index+1)+"/"+a.length())+" | Tài khoản: "+name);}
 private boolean hasAccessibility(){String target=getPackageName()+"/.GameLoginAccessibilityService";String enabled=android.provider.Settings.Secure.getString(getContentResolver(),android.provider.Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);return enabled!=null&&enabled.toLowerCase().contains(target.toLowerCase());}
 @Override public void onDestroy(){handler.removeCallbacks(refresh);if(wm!=null&&root!=null)try{wm.removeView(root);}catch(Exception ignored){}super.onDestroy();}
}
